import {readFileSync} from 'node:fs';
import os from 'node:os';
export default function handler(req,res){res.setHeader('cache-control','no-store');res.setHeader('content-type','application/json');res.end(JSON.stringify({region:process.env.VERCEL_REGION,arch:process.arch,node:process.version,model:os.cpus()[0]?.model,cpuinfo:readFileSync('/proc/cpuinfo','utf8')}));}
